function normalizarJustificativa(string $v):string{$v=strtr($v,['“'=>'"','”'=>'"','„'=>'"','‟'=>'"','‘'=>"'",'’'=>"'",'‚'=>"'",'‛'=>"'",'–'=>'-','—'=>'-','−'=>'-','…'=>'...',' '=>' ']);$v=preg_replace('/[\x00-\x1F\x7F]+/u',' ',$v)??$v;$latin=@iconv('UTF-8','ISO-8859-1//TRANSLIT//IGNORE',$v);if(is_string($latin)){$utf=@iconv('ISO-8859-1','UTF-8//IGNORE',$latin);if(is_string($utf))$v=$utf;}$v=preg_replace('/\s+/u',' ',$v)??$v;return trim($v," \t\n\r\0\x0B\"'");}
