function paths():array{$h=homeDir();return ['secret'=>$h.'/.synergias-secrets/fiscal-a1.key','data'=>$h.'/synergias_private/fiscal-a1/certificado.a1.enc.json','dir'=>$h.'/synergias_private/fiscal-nfe','ca'=>__DIR__.'/cacert.pem'];}
