function assinarEvento(DOMDocument $d,DOMElement $inf,array $m):void{$id=$inf->getAttribute('Id');$digest=base64_encode(hash('sha1',$inf->C14N(false,false),true));$evento=$inf->parentNode;if(!$evento instanceof DOMElement)throw new RuntimeException('Evento inválido.');$sig=$d->createElementNS(DS_NS,'Signature');$si=$d->createElementNS(DS_NS,'SignedInfo');$sig->appendChild($si);$cm=$d->createElementNS(DS_NS,'CanonicalizationMethod');$cm->setAttribute('Algorithm','http://www.w3.org/TR/2001/REC-xml-c14n-20010315');$si->appendChild($cm);$sm=$d->createElementNS(DS_NS,'SignatureMethod');$sm->setAttribute('Algorithm','http://www.w3.org/2000/09/xmldsig#rsa-sha1');$si->appendChild($sm);$ref=$d->createElementNS(DS_NS,'Reference');$ref->setAttribute('URI','#'.$id);$si->appendChild($ref);$trs=$d->createElementNS(DS_NS,'Transforms');$ref->appendChild($trs);foreach(['http://www.w3.org/2000/09/xmldsig#enveloped-signature','http://www.w3.org/TR/2001/REC-xml-c14n-20010315'] as $alg){$t=$d->createElementNS(DS_NS,'Transform');$t->setAttribute('Algorithm',$alg);$trs->appendChild($t);} $dm=$d->createElementNS(DS_NS,'DigestMethod');$dm->setAttribute('Algorithm','http://www.w3.org/2000/09/xmldsig#sha1');$ref->appendChild($dm);addEl($d,$ref,'DigestValue',$digest,DS_NS);$evento->appendChild($sig);$raw='';if(!openssl_sign($si->C14N(false,false),$raw,$m['key'],OPENSSL_ALGO_SHA1))throw new RuntimeException('Falha ao assinar evento.');addEl($d,$sig,'SignatureValue',base64_encode($raw),DS_NS);$ki=$d->createElementNS(DS_NS,'KeyInfo');$sig->appendChild($ki);$xd=$d->createElementNS(DS_NS,'X509Data');$ki->appendChild($xd);addEl($d,$xd,'X509Certificate',certB64($m['cert']),DS_NS);}
