function transmitir(string $xml,string $amb,array $m):string{$url=$amb==='PRODUCAO'?'https://nfe.sefazrs.rs.gov.br/ws/recepcaoevento/recepcaoevento4.asmx':'https://nfe-homologacao.sefazrs.rs.gov.br/ws/recepcaoevento/recepcaoevento4.asmx';$body='<?xml version="1.0" encoding="UTF-8"?><soap12:Envelope xmlns:soap12="http://www.w3.org/2003/05/soap-envelope"><soap12:Body><nfeDadosMsg xmlns="http://www.portalfiscal.inf.br/nfe/wsdl/NFeRecepcaoEvento4">'.$xml.'</nfeDadosMsg></soap12:Body></soap12:Envelope>';$cert=$m['cert'];foreach($m['extras'] as $x)if(is_string($x)&&trim($x)!=='')$cert.="\n".trim($x)."\n";$cf=tempPem('cert',$cert);$kf=tempPem('key',$m['key']);try{$ch=curl_init($url);$opts=[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$body,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>90,CURLOPT_CONNECTTIMEOUT=>25,CURLOPT_SSLCERT=>$cf,CURLOPT_SSLKEY=>$kf,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_HTTPHEADER=>['Content-Type: application/soap+xml; charset=utf-8; action="http://www.portalfiscal.inf.br/nfe/wsdl/NFeRecepcaoEvento4/nfeRecepcaoEvento"']];$p=paths();if(is_file($p['ca']))$opts[CURLOPT_CAINFO]=$p['ca'];curl_setopt_array($ch,$opts);$r=curl_exec($ch);$err=curl_error($ch);$no=curl_errno($ch);$http=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if($no!==0||!is_string($r)||$r==='')throw new RuntimeException('Falha na transmissão SEFAZ: '.$err.' (cURL '.$no.', HTTP '.$http.').');return $r;}finally{@unlink($cf);@unlink($kf);}}
try{if(strtoupper(txt($_SERVER['REQUEST_METHOD']??''))!=='POST')out(405,['ok'=>false,'mensagem'=>'Método não permitido.']);$u=exigirAutenticacao();if(strcasecmp(txt($u['perfil']??''),'Administrador')!==0)out(403,['ok'=>false,'mensagem'=>'Apenas Administrador.']);$b=json_decode((string)file_get_contents('php://input'),true);$chave=preg_replace('/\D+/','',txt($b['chaveAcesso']??''))?:'';$prot=txt($b['protocoloAutorizacao']??'');$just=normalizarJustificativa(txt($b['justificativa']??''));$amb=strtoupper(txt($b['ambiente']??'HOMOLOGACAO'));if(strlen($chave)!==44)throw new RuntimeException('Chave de acesso inválida.');if($prot==='')throw new RuntimeException('Protocolo de autorização ausente.');if(mb_strlen($just)<15||mb_strlen($just)>255)throw new RuntimeException('Justificativa deve ter entre 15 e 255 caracteres.');$cnpj=substr($chave,6,14);$tpAmb=$amb==='PRODUCAO'?'1':'2';$dh=(new DateTimeImmutable('now',new DateTimeZone('America/Sao_Paulo')))->format('Y-m-d\TH:i:sP');$id='ID110111'.$chave.'01';$d=new DOMDocument('1.0','UTF-8');$d->preserveWhiteSpace=false;$d->formatOutput=false;$env=$d->createElementNS(NFE_NS,'envEvento');$env->setAttribute('versao','1.00');$d->appendChild($env);addEl($d,$env,'idLote',(string)time(),NFE_NS);$ev=$d->createElementNS(NFE_NS,'evento');$ev->setAttribute('versao','1.00');$env->appendChild($ev);$inf=$d->createElementNS(NFE_NS,'infEvento');$inf->setAttribute('Id',$id);$ev->appendChild($inf);addEl($d,$inf,'cOrgao','43',NFE_NS);addEl($d,$inf,'tpAmb',$tpAmb,NFE_NS);addEl($d,$inf,'CNPJ',$cnpj,NFE_NS);addEl($d,$inf,'chNFe',$chave,NFE_NS);addEl($d,$inf,'dhEvento',$dh,NFE_NS);addEl($d,$inf,'tpEvento','110111',NFE_NS);addEl($d,$inf,'nSeqEvento','1',NFE_NS);addEl($d,$inf,'verEvento','1.00',NFE_NS);$det=$d->createElementNS(NFE_NS,'detEvento');$det->setAttribute('versao','1.00');$inf->appendChild($det);addEl($d,$det,'descEvento','Cancelamento',NFE_NS);addEl($d,$det,'nProt',$prot,NFE_NS);addEl($d,$det,'xJust',$just,NFE_NS);$m=materialA1();assinarEvento(